pub type ConfigError = enum {
  FileNotFound(path: Str),
  InvalidSyntax(line: Int, message: Str),
}

fn read_config(path: Str) -> Result[Str, ConfigError] {
  if path.len() == 0 {
    return Err(ConfigError::FileNotFound("empty path"));
  }
  return Ok("server.port=8080");
}

fn main() -> Int {
  match read_config("config.xi") {
    Ok(_) => return 1,
    Err(_) => return 0,
  }
}
